(()=>{const ticker=document.querySelector('.notice-ticker');if(!ticker)return;const items=ticker.querySelector('.notice-ticker-items');const copy=items.cloneNode(true);copy.setAttribute('aria-hidden','true');copy.inert=true;ticker.querySelector('.notice-ticker-track').append(copy);const button=ticker.querySelector('button');button.addEventListener('click',()=>{const paused=ticker.classList.toggle('is-paused');button.textContent=paused?'Play':'Pause';button.setAttribute('aria-pressed',String(paused));button.setAttribute('aria-label',paused?'Resume scrolling notices':'Pause scrolling notices')})})();
